// Split the 33-word codes of Z_7^3 into orbits under the group G generated by coordinate
// permutations and the maps v -> s v + t (s = +-1) of each coordinate; |G| = 6*8*343 = 16464.
// Input codes33.bin (sorted), output classes33.txt: one line per orbit with its least member
// (as 33 point indices 49u+7a+b) and the orbit size.
#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64; typedef array<u64,6> Code;
int main(){
  FILE*f=fopen("codes33.bin","rb");fseek(f,0,SEEK_END);size_t n=ftell(f)/sizeof(Code);fseek(f,0,SEEK_SET);
  vector<Code> codes(n);if(fread(codes.data(),sizeof(Code),n,f)!=n)return 1;fclose(f);
  for(size_t i=1;i<n;i++)assert(codes[i-1]<codes[i]);
  vector<char> seen(n,0);
  int perms[6][3]={{0,1,2},{0,2,1},{1,0,2},{1,2,0},{2,0,1},{2,1,0}};
  FILE*o=fopen("classes33.txt","w");
  size_t classes=0,total=0;
  for(size_t i=0;i<n;i++){
    if(seen[i])continue;
    vector<array<int,3>> pts;
    for(int idx=0;idx<343;idx++)if(codes[i][idx>>6]>>(idx&63)&1)pts.push_back({idx/49,idx/7%7,idx%7});
    assert(pts.size()==33);
    set<size_t> orbit;
    for(auto&p:perms)for(int s=0;s<8;s++)for(int t=0;t<343;t++){
      int tt[3]={t/49,t/7%7,t%7};Code c{};
      for(auto&q:pts){int v[3];for(int k=0;k<3;k++){int x=q[p[k]];if(s>>k&1)x=(7-x)%7;v[k]=(x+tt[k])%7;}int idx=49*v[0]+7*v[1]+v[2];c[idx>>6]|=1ULL<<(idx&63);}
      auto it=lower_bound(codes.begin(),codes.end(),c);
      assert(it!=codes.end()&&*it==c);
      orbit.insert(it-codes.begin());
    }
    assert(*orbit.begin()==i);
    for(size_t j:orbit)seen[j]=1;
    classes++;total+=orbit.size();
    fprintf(o,"%zu",orbit.size());
    for(int idx=0;idx<343;idx++)if(codes[i][idx>>6]>>(idx&63)&1)fprintf(o," %d",idx);
    fprintf(o,"\n");
  }
  fclose(o);
  printf("codes %zu classes %zu total %zu\n",n,classes,total);
}
